# مولّد الخطط الدراسية لجامعة بنيان العالمية — يتحقق من المجاميع والتسلسل ثم يكتب inc/curriculum_seed.json
import json, sys, re

# ---------- المراجع ----------
# (اللغة، التصنيف، الجودة، العنوان، المؤلف)
A, S, E = 'main', 'support', 'extra'          # أساسي / مساند / إثرائي
QE, QA, QD = 'verified', 'approved', 'dept'   # طبعة محققة / معتمد أكاديميًا / مذكرة القسم
def ar(t, a, c=A, q=QE): return ['ar', c, q, t, a]
def en(t, a, c=S, q=QA): return ['en', c, q, t, a]
DEPT = [ar('مذكرة المقرر المعتمدة من القسم', 'القسم العلمي', A, QD)]

C = {}  # الكتالوج
def course(code, n, e, cr, pre=(), t='M', d='', refs=None):
    assert code not in C, code
    C[code] = {'n': n, 'en': e, 'bn': '', 'ur': '', 'cr': cr, 'pre': list(pre), 't': t, 'd': d, 'refs': refs or DEPT}

