# الدكتوراه (42 ساعة: 24 مقررات وسيمينار + 18 أطروحة)
def phd(px, titles):
    for i, (n, e) in enumerate(titles[:3]): gcourse(px + '70%d' % (i + 1), n, e, d='مقرر متقدم في التخصص لمرحلة الدكتوراه.')
    for i, (n, e) in enumerate(titles[3:6]): gcourse(px + '71%d' % (i + 1), n, e, pre=[px + '70%d' % (i + 1)] if i < 2 else [px + '701'], d='مقرر متقدم في التخصص لمرحلة الدكتوراه.')
    gcourse(px + '780', 'الاختبار الشامل', 'Comprehensive Examination', 0, [px + '711', px + '712', px + '713'], 'P', 'اختبار تحريري وشفهي في التخصص شرط للانتقال إلى مرحلة الأطروحة.')
    gcourse(px + '790', 'خطة الأطروحة', 'Dissertation Proposal', 3, [px + '713'], 'P', 'إعداد خطة الأطروحة وإجازتها.')
    gcourse(px + '791', 'النشر العلمي المحكم', 'Peer-Reviewed Publication', 3, [px + '713'], 'P', 'نشر بحث في مجلة علمية محكمة ومفهرسة.')
    gcourse(px + '801', 'الأطروحة 1', 'Dissertation 1', 6, [px + '780', px + '790'], 'P', 'العمل في الأطروحة بإشراف المشرف — التقرير الأول.')
    gcourse(px + '802', 'الأطروحة 2', 'Dissertation 2', 6, [px + '801'], 'P', 'العمل في الأطروحة — التقرير الثاني.')
    gcourse(px + '803', 'الأطروحة 3 والمناقشة', 'Dissertation 3 & Defense', 6, [px + '802'], 'P', 'استكمال الأطروحة ومناقشتها علنيًا.')
