# ---------- التحقق ----------
errs = []
for s, p in P.items():
    seen = {}; tot = 0
    for i, lv in enumerate(p['levels']):
        h = 0
        for c in lv['c']:
            if c not in C: errs.append('%s: مقرر غير معرّف %s' % (s, c)); continue
            if c in seen: errs.append('%s: مكرر %s' % (s, c))
            for pr in C[c]['pre']:
                if pr not in seen: errs.append('%s: %s يتطلب %s ولم يُدرس قبله' % (s, c, pr))
            h += C[c]['cr']
        for c in lv['c']: seen[c] = i
        lv_max = 19 if p['unit'] == 'cr' and p['stage'] == 'bac' else 999
        if h > lv_max: errs.append('%s: %s = %d ساعة (> %d)' % (s, lv['n'], h, lv_max))
        tot += h
        print('%-20s %-14s %4d' % (s, lv['n'], h))
    print('%-20s %-14s %4d / %d' % (s, 'المجموع', tot, p['target']))
    if tot != p['target']: errs.append('%s: المجموع %d لا يساوي %d' % (s, tot, p['target']))
used = {c for p in P.values() for lv in p['levels'] for c in lv['c']}
for c in C:
    if c not in used: errs.append('مقرر غير مستخدم: ' + c)
if errs:
    print('\n'.join(errs)); sys.exit(1)

